+type signalingBody struct {
+	io.ReadCloser
+	started chan struct{}
+	once    sync.Once
+	closes  atomic.Int32
+}
+
+func (b *signalingBody) Read(p []byte) (int, error) {
+	b.once.Do(func() { close(b.started) })
+	return b.ReadCloser.Read(p)
+}
+
+func (b *signalingBody) Close() error {
+	b.closes.Add(1)
+	return b.ReadCloser.Close()
+}
