+func waitForSignal(t *testing.T, done <-chan struct{}, operation string) bool {
+	t.Helper()
+	timer := time.NewTimer(waitLimit)
+	defer timer.Stop()
+	select {
+	case <-done:
+		return true
+	case <-timer.C:
+		t.Errorf("timed out waiting for %s", operation)
+		return false
 	}
 }
